import { resourceList, knowledgeDelete, collect, resourceLearn, knowledgePage, collectDelete } from "@/api/ictOperation/index"
import operateForm from '../intelligenceAnswer/operateForm'
import {mapGetters,mapState} from "vuex";

export default {
  props: ['searchText'],
  components: { operateForm },
  data() {
    return{
      activeName: '0',
      tabsList: [
        {name: '全部', activeName: '0'},
        {name: '待审核', activeName: '1'},
        {name: '已审核', activeName: '2'},
        {name: '驳回', activeName: '3'}
      ],

      showOperate: false,
      questionId: undefined,

      resourceData: [],
      total: 0,
      searchForm: {
        current: 1,
        size: 20,
        tag: 0,
        resourceCondition: '',
        view: 0
      },
      pageLoading: false,
    }
  },
  computed: {
    ...mapGetters(["permission", "userInfo"]),
    isRoleAlias(){
      return this.$store.state.user.userDetail.roleAlias.includes('control_solver')
    }
  },
  mounted() {
    this.getList()
  },
  methods: {
    handleTitle(item){
      // console.log(90, item)
      // return
      if(item.status == 1){
        this.handle1(item)
      }else{
        this.seeDetail(item)
      }
    },
    handleTabsItem(item, index) {
      this.activeName = item.activeName
      this.searchForm.view = item.activeName
      this.getList()
    },

    showDictLable(status){
      switch (status) {
        case '0':
          return '暂存'
          // break;
        case '1':
          return '待审核'
          // break;
        case '2':
          return '已审核'
        case '3':
          return '驳回'
          // break;
          // default:
      }
    },
    showDictLable2(status){
      switch (status) {
        case '0':
          return 'warning'
          // break;
        case '1':
          return 'success'
          // break;
        case '2':
          return 'info'
        case '3':
          return 'danger'
      }
    },

    handle1(item){
      this.$emit('handleShenpi', item)
      // this.questionId = item.id
      // this.showOperate = true
    },
    submitProcess(){
      this.showOperate = false
      this.getList()
    },

    getList() {
      this.pageLoading = true
      knowledgePage(this.searchForm).then(res => {
        this.resourceData = res.data.records
        this.total = res.data.total
        this.pageLoading = false
      })
    },
    search() {
      this.searchForm.current = 1
      this.searchForm.resourceCondition = this.searchText
      this.getList()
    },
    seeDetail(item, index) {
      this.$emit('seeProblem', item)
      // this.$router.push({
      //   path: '/resourceDetail',
      //   query: {id: item.id, type: '文档'}
      // })
    }, 

    del(item){
      this.$confirm("是否确认删除!","提示",{
        confirmButtonText:"确认",
        cancelButtonText:"取消",
        type:"warning"
      }).then(()=>{
          knowledgeDelete({id: item.id}).then(res=>{
            this.getList()
            // this.$emit('refresh', '0')
            this.$message.success('删除成功!')
          })  
      })

    },
    collect(item){
      collect({
        knowledgeId: item.id, 
        isDeleted: 0,
        userId: this.userInfo.userId 
      }).then(res=>{
        this.getList()
        this.$message.success('操作成功!')
      }) 
    },
    collect2(item){
      collectDelete({id: item.id}).then(res => {
        this.getList()
        this.$message.success('操作成功!')
      })
    },
    learn(item){
      resourceLearn({
        type: 0,
        knowledgeId: item.id,
        userId: this.userInfo.userId 
      }).then(res=>{
        this.getList()
        this.$message.success('操作成功!')
      }) 
    },


  }
}
